window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-81986ec0ac893207"]={"versions": [{"id": "FIG-81986ec0ac893207", "releases": ["R1.3.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion bzw. des Algorithmus <code>Increment Counter</code> (bzw. <code>Increment State-&gt;Counter</code>) innerhalb des AUTOSAR E2E-Protokolls (PRS E2EProtocol). Das Diagramm beschreibt die Aktualisierungslogik des Übertragungszählers (<code>Counter</code>) im Zustandsraum des Senders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Startknoten</strong>: Initialer Kontrollflusseinstiegspunkt, annotiert mit <code>Increment State-&gt;Counter</code>.</li>\n<li><strong>Entscheidungsknoten (Decision Node)</strong>: Verzweigungsraute mit einer Prüfbedingung bezüglich <code>State-&gt;Counter</code> (abgeschnittene Darstellung <code>State-&gt;Cou... ?</code>), die die Pfade <code>[TRUE]</code> und <code>[FALSE]</code> steuert.</li>\n<li><strong>Aktionszustand 1</strong>: <code>State-&gt;Counter ++</code> (Inkrementierung des Zählers).</li>\n<li><strong>Aktionszustand 2</strong>: <code>State-&gt; Counter = 0</code> (Zurücksetzen des Zählers auf 0 bei Überlauf).</li>\n<li><strong>Zusammenführungsknoten (Merge Node)</strong>: Vereinigt die beiden Ausführungspfade.</li>\n<li><strong>Aktivitätsendknoten</strong>: Beendet die Inkrementierungsaktivität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten für die Ausführung von <code>Increment State-&gt;Counter</code>.</li>\n<li>Am ersten Entscheidungsknoten wird geprüft, ob der Zählerwert noch unterhalb der maximalen Grenze liegt (<code>[TRUE]</code>) oder der Maximalwert erreicht ist (<code>[FALSE]</code>).</li>\n<li>Ergibt die Auswertung <code>[TRUE]</code>, wird die Aktion <code>State-&gt;Counter ++</code> ausgeführt.</li>\n<li>Ergibt die Auswertung <code>[FALSE]</code>, wird die Aktion <code>State-&gt; Counter = 0</code> ausgeführt.</li>\n<li>Beide Ausführungspfade laufen im Zusammenführungsknoten zusammen und führen direkt zum Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das deterministische Verhalten zur zyklischen Fortschreibung des E2E-Counters bei Protokoll-Nachrichten zur Erkennung von Datenverlust, Wiederholungen oder Sequenzfehlern. Entwickler müssen sicherstellen, dass der Zähler beim Erreichen des oberen Grenzwertes (typischerweise 14 bzw. Modulo-16-Arithmetik für 4-Bit-Zähler bis 15) konsistent auf 0 zurückgesetzt wird, um einen synchronen Zählerbereich zwischen Sender und Empfänger zu gewährleisten.</p>"}, {"id": "FIG-3d30d171b43656c1", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion bzw. des Algorithmus <code>Increment Counter</code> (bzw. <code>Increment State-&gt;Counter</code>) innerhalb des AUTOSAR E2E-Protokolls (PRS E2EProtocol). Das Diagramm beschreibt die Aktualisierungslogik des Übertragungszählers (<code>Counter</code>) im Zustandsraum des Senders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Startknoten</strong>: Initialer Kontrollflusseinstiegspunkt, annotiert mit <code>Increment State &gt;Counter</code>.</li>\n<li><strong>Entscheidungsknoten (Decision Node)</strong>: Verzweigungsraute mit der Prüfbedingung bezüglich des Zählergrenzwerts (<code>State-&gt;Cou... 15 ?</code>), die in die Pfade <code>[TRUE]</code> und <code>[FALSE]</code> verzweigt.</li>\n<li><strong>Aktionszustand 1</strong>: <code>State-&gt;Counter ++</code> (Inkrementierung des Zählers).</li>\n<li><strong>Aktionszustand 2</strong>: <code>State-&gt; Counter = 0</code> (Zurücksetzen des Zählers auf 0).</li>\n<li><strong>Zusammenführungsknoten (Merge Node)</strong>: Führt die beiden alternativen Kontrollflusspfade zusammen.</li>\n<li><strong>Aktivitätsendknoten</strong>: Finaler Endknoten der Aktivität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten für die Ausführung von <code>Increment State-&gt;Counter</code>.</li>\n<li>Am ersten Entscheidungsknoten wird geprüft, ob der Zählerwert noch unterhalb der maximalen Grenze liegt (<code>[TRUE]</code>) oder der Maximalwert erreicht ist (<code>[FALSE]</code>).</li>\n<li>Ergibt die Auswertung <code>[TRUE]</code>, wird die Aktion <code>State-&gt;Counter ++</code> ausgeführt.</li>\n<li>Ergibt die Auswertung <code>[FALSE]</code>, wird die Aktion <code>State-&gt; Counter = 0</code> ausgeführt.</li>\n<li>Beide Ausführungspfade laufen im Zusammenführungsknoten zusammen und führen direkt zum Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das deterministische Verhalten zur zyklischen Fortschreibung des E2E-Counters bei Protokoll-Nachrichten zur Erkennung von Datenverlust, Wiederholungen oder Sequenzfehlern. Entwickler müssen sicherstellen, dass der Zähler beim Erreichen des oberen Grenzwertes (typischerweise 14 bzw. Modulo-16-Arithmetik für 4-Bit-Zähler bis 15) konsistent auf 0 zurückgesetzt wird, um einen synchronen Zählerbereich zwischen Sender und Empfänger zu gewährleisten.</p>"}, {"id": "FIG-0c08a6fe19bfbfd0", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion bzw. des Algorithmus <code>Increment Counter</code> (bzw. <code>Increment State-&gt;Counter</code>) innerhalb des AUTOSAR E2E-Protokolls (PRS E2EProtocol). Das Diagramm beschreibt die Aktualisierungslogik des Übertragungszählers (<code>Counter</code>) im Zustandsraum des Senders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Startknoten</strong>: Initialer Kontrollflusseinstiegspunkt, annotiert mit <code>Increment State-&gt;Counter</code>.</li>\n<li><strong>Entscheidungsknoten (Decision Node)</strong>: Verzweigungsraute mit einer Prüfbedingung bezüglich <code>State-&gt;Counter</code> (abgeschnittene Darstellung <code>State-&gt;Cou... ?</code>), die die Pfade <code>[TRUE]</code> und <code>[FALSE]</code> steuert.</li>\n<li><strong>Aktionszustand 1</strong>: <code>State-&gt;Counter ++</code> (Inkrementierung des Zählers).</li>\n<li><strong>Aktionszustand 2</strong>: <code>State-&gt; Counter = 0</code> (Zurücksetzen des Zählers auf 0 bei Überlauf).</li>\n<li><strong>Zusammenführungsknoten (Merge Node)</strong>: Vereinigt die beiden Ausführungspfade.</li>\n<li><strong>Aktivitätsendknoten</strong>: Beendet die Inkrementierungsaktivität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten für die Ausführung von <code>Increment State-&gt;Counter</code>.</li>\n<li>Am ersten Entscheidungsknoten wird geprüft, ob der Zählerwert noch unterhalb der maximalen Grenze liegt (<code>[TRUE]</code>) oder der Maximalwert erreicht ist (<code>[FALSE]</code>).</li>\n<li>Ergibt die Auswertung <code>[TRUE]</code>, wird die Aktion <code>State-&gt;Counter ++</code> ausgeführt.</li>\n<li>Ergibt die Auswertung <code>[FALSE]</code>, wird die Aktion <code>State-&gt; Counter = 0</code> ausgeführt.</li>\n<li>Beide Ausführungspfade laufen im Zusammenführungsknoten zusammen und führen direkt zum Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das deterministische Verhalten zur zyklischen Fortschreibung des E2E-Counters bei Protokoll-Nachrichten zur Erkennung von Datenverlust, Wiederholungen oder Sequenzfehlern. Entwickler müssen sicherstellen, dass der Zähler beim Erreichen des oberen Grenzwertes (typischerweise 14 bzw. Modulo-16-Arithmetik für 4-Bit-Zähler bis 15) konsistent auf 0 zurückgesetzt wird, um einen synchronen Zählerbereich zwischen Sender und Empfänger zu gewährleisten.</p>"}, {"id": "FIG-d0a51015bb5e06b6", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses bei der Zählerinkrementierung (Increment Counter / Increment State->Counter) im AUTOSAR E2E-Protokoll (PRS_E2EProtocol). Das Diagramm modelliert einen zyklischen Modulo-16-Zählmechanismus innerhalb des E2E-Zustandsmanagements.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Entitäten / Zustandsvariablen: <code>State-&gt;Counter</code> (Zählerwert im Sender-/Empfängerzustand, Wertebereich 0 bis 15).</li>\n<li>Kontrollknoten: Startknoten (Initial Node) mit Beschriftung <code>Increment State-&gt;Counter</code>, Verzweigungsknoten (Decision Node) zur Schwellwertprüfung, Zusammenführungsknoten (Merge Node), Endknoten (Activity Final Node).</li>\n<li>Aktionen: Inkrementierungsaktion <code>State-&gt;Counter ++</code>, Reset-Aktion <code>State-&gt; Counter = 0</code>.</li>\n<li>Kontrollflüsse mit Guards: <code>[TRUE]</code> leitet auf <code>State-&gt;Counter ++</code>, <code>[FALSE]</code> leitet auf <code>State-&gt; Counter = 0</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet am Initial Node <code>Increment State-&gt;Counter</code>.</li>\n<li>Am ersten Entscheidungsknoten wird die Bedingung <code>State-&gt;Counter &lt; 15 ?</code> (im Bild als <code>State-&gt;Cou... 15 ?</code> abgeschnitten dargestellt) ausgewertet.</li>\n<li>Ist die Bedingung erfüllt (<code>[TRUE]</code>), wird die Aktion <code>State-&gt;Counter ++</code> ausgeführt.</li>\n<li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>, d. h. der Zähler hat den Maximalwert 15 erreicht), wird die Aktion <code>State-&gt; Counter = 0</code> ausgeführt.</li>\n<li>Beide Ausführungspfade laufen an einem Merge Node zusammen und terminieren im Activity Final Node.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Algorithmus zur Zählerweiterschaltung in 4-Bit-E2E-Profilen (Überlauf bei Erreichen von 15 zurück auf 0). Bei der Implementierung ist sicherzustellen, dass die Bedingung atomar vor der Paketabsendung bzw. im Rahmen der E2E-Protect-Routine ausgewertet wird.</p>"}, {"id": "FIG-e8d6bf22ea92caf7", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses bei der zustandsabhängigen Zähleranpassung und -inkrementierung (Increment State->Counter) im AUTOSAR E2E-Protokoll (PRS_E2EProtocol). Das Diagramm modelliert die Vorwärtsstatus-Behandlung bei Nachrichtenweiterleitung sowie das zyklische Inkrementieren eines 4-Bit-Modulo-16-Zählers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Daten- und Zustandsstrukturen: <code>State-&gt;Counter</code> (Zählerwert), <code>Config-&gt;MaxDeltaCounterInit</code> (Konfigurationsparameter für den maximal zulässigen Zählersprung beim Initialisieren/Synchronisieren), <code>ForwardStatus</code> (Statusflag zur Sequenzintegrität mit Werten wie <code>E2E_P_REPEATED</code> und <code>E2E_P_WRONGSEQUENCE</code>).</li>\n<li>Kontrollknoten: Startknoten <code>Increment State-&gt;Counter</code>, drei aufeinanderfolgende Entscheidungsknoten (Decision Nodes), ein Zusammenführungsknoten (Merge Node), Endknoten (Activity Final Node).</li>\n<li>Aktionen: Zählersprung <code>State-&gt; Counter += Config-&gt;MaxDeltaCounterInit + 1</code>, Zähler-Reset <code>State-&gt; Counter = 0</code>, Inkrementierung <code>State-&gt;Counter ++</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Startknoten <code>Increment State-&gt;Counter</code>.</li>\n<li>Erster Verzweigungsknoten prüft, ob eine Wiederholung vorliegt (<code>ForwardStatus == E2E_P_REPEATED</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Keine Anpassung des Zählers; der Pfad führt direkt zum Zusammenführungsknoten.</li>\n<li>Wenn <code>[FALSE]</code>: Übergang zum zweiten Entscheidungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweiter Verzweigungsknoten prüft <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Ausführung von <code>State-&gt; Counter += Config-&gt;MaxDeltaCounterInit + 1</code>, danach Übergang zum Zusammenführungsknoten.</li>\n<li>Wenn <code>[FALSE]</code>: Übergang zum dritten Entscheidungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Dritter Verzweigungsknoten prüft den Überlauf <code>State-&gt;Counter &gt;= 15 ?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Ausführung von <code>State-&gt; Counter = 0</code>.</li>\n<li>Wenn <code>[FALSE]</code>: Ausführung von <code>State-&gt;Counter ++</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Alle drei aktiven Zweige bzw. der Bypass-Zweig münden im gemeinsamen Zusammenführungsknoten und enden im Final Node.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert das Verhalten bei fehlerhaften Sequenzen (<code>E2E_P_WRONGSEQUENCE</code>) und wiederholten Botschaften (<code>E2E_P_REPEATED</code>) im Forwarding-/Gateway-Szenario des E2E-Protokolls. Für Implementierer ist relevant, dass ein Sequenzfehler einen gezielten Sprung über das Akzeptanzfenster (<code>MaxDeltaCounterInit + 1</code>) erzwingt, während bei Duplikaten keine Zählerfortschaltung stattfindet. Bei normalem Fluss wird der Zähler modulo 16 zyklisch geführt.</p>"}, {"id": "FIG-175bbecfc579b04f", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses bei der Zählerinkrementierung (Increment Counter / Increment State->Counter) im AUTOSAR E2E-Protokoll (PRS_E2EProtocol). Das Diagramm modelliert einen zyklischen Modulo-16-Zählmechanismus innerhalb des E2E-Zustandsmanagements.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Entitäten / Zustandsvariablen: <code>State-&gt;Counter</code> (Zählerwert im Sender-/Empfängerzustand, Wertebereich 0 bis 15).</li>\n<li>Kontrollknoten: Startknoten (Initial Node) mit Beschriftung <code>Increment State-&gt;Counter</code>, Verzweigungsknoten (Decision Node) zur Schwellwertprüfung, Zusammenführungsknoten (Merge Node), Endknoten (Activity Final Node).</li>\n<li>Aktionen: Inkrementierungsaktion <code>State-&gt;Counter ++</code>, Reset-Aktion <code>State-&gt; Counter = 0</code>.</li>\n<li>Kontrollflüsse mit Guards: <code>[TRUE]</code> leitet auf <code>State-&gt;Counter ++</code>, <code>[FALSE]</code> leitet auf <code>State-&gt; Counter = 0</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet am Initial Node <code>Increment State-&gt;Counter</code>.</li>\n<li>Am ersten Entscheidungsknoten wird die Bedingung <code>State-&gt;Counter &lt; 15 ?</code> (im Bild als <code>State-&gt;Cou... 15 ?</code> abgeschnitten dargestellt) ausgewertet.</li>\n<li>Ist die Bedingung erfüllt (<code>[TRUE]</code>), wird die Aktion <code>State-&gt;Counter ++</code> ausgeführt.</li>\n<li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>, d. h. der Zähler hat den Maximalwert 15 erreicht), wird die Aktion <code>State-&gt; Counter = 0</code> ausgeführt.</li>\n<li>Beide Ausführungspfade laufen an einem Merge Node zusammen und terminieren im Activity Final Node.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Algorithmus zur Zählerweiterschaltung in 4-Bit-E2E-Profilen (Überlauf bei Erreichen von 15 zurück auf 0). Bei der Implementierung ist sicherzustellen, dass die Bedingung atomar vor der Paketabsendung bzw. im Rahmen der E2E-Protect-Routine ausgewertet wird.</p>"}, {"id": "FIG-ad22485ff61b6499", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses bei der zustandsabhängigen Zähleranpassung und -inkrementierung (Increment State->Counter) im AUTOSAR E2E-Protokoll (PRS_E2EProtocol). Das Diagramm modelliert die Vorwärtsstatus-Behandlung bei Nachrichtenweiterleitung sowie das zyklische Inkrementieren eines 4-Bit-Modulo-16-Zählers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Daten- und Zustandsstrukturen: <code>State-&gt;Counter</code> (Zählerwert), <code>Config-&gt;MaxDeltaCounterInit</code> (Konfigurationsparameter für den maximal zulässigen Zählersprung beim Initialisieren/Synchronisieren), <code>ForwardStatus</code> (Statusflag zur Sequenzintegrität mit Werten wie <code>E2E_P_REPEATED</code> und <code>E2E_P_WRONGSEQUENCE</code>).</li>\n<li>Kontrollknoten: Startknoten <code>Increment State-&gt;Counter</code>, drei aufeinanderfolgende Entscheidungsknoten (Decision Nodes), ein Zusammenführungsknoten (Merge Node), Endknoten (Activity Final Node).</li>\n<li>Aktionen: Zählersprung <code>State-&gt; Counter += Config-&gt;MaxDeltaCounterInit + 1</code>, Zähler-Reset <code>State-&gt; Counter = 0</code>, Inkrementierung <code>State-&gt;Counter ++</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Startknoten <code>Increment State-&gt;Counter</code>.</li>\n<li>Erster Verzweigungsknoten prüft, ob eine Wiederholung vorliegt (<code>ForwardStatus == E2E_P_REPEATED</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Keine Anpassung des Zählers; der Pfad führt direkt zum Zusammenführungsknoten.</li>\n<li>Wenn <code>[FALSE]</code>: Übergang zum zweiten Entscheidungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweiter Verzweigungsknoten prüft <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Ausführung von <code>State-&gt; Counter += Config-&gt;MaxDeltaCounterInit + 1</code>, danach Übergang zum Zusammenführungsknoten.</li>\n<li>Wenn <code>[FALSE]</code>: Übergang zum dritten Entscheidungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Dritter Verzweigungsknoten prüft den Überlauf <code>State-&gt;Counter &gt;= 15 ?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Ausführung von <code>State-&gt; Counter = 0</code>.</li>\n<li>Wenn <code>[FALSE]</code>: Ausführung von <code>State-&gt;Counter ++</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Alle drei aktiven Zweige bzw. der Bypass-Zweig münden im gemeinsamen Zusammenführungsknoten und enden im Final Node.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert das Verhalten bei fehlerhaften Sequenzen (<code>E2E_P_WRONGSEQUENCE</code>) und wiederholten Botschaften (<code>E2E_P_REPEATED</code>) im Forwarding-/Gateway-Szenario des E2E-Protokolls. Für Implementierer ist relevant, dass ein Sequenzfehler einen gezielten Sprung über das Akzeptanzfenster (<code>MaxDeltaCounterInit + 1</code>) erzwingt, während bei Duplikaten keine Zählerfortschaltung stattfindet. Bei normalem Fluss wird der Zähler modulo 16 zyklisch geführt.</p>"}, {"id": "FIG-b0205af06f54761f", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Modellierung des Kontrollflusses bei der Zählerinkrementierung (<code>Increment State-&gt;Counter</code>) für den 4-Bit-Zähler im AUTOSAR E2E-Protokoll (PRS_E2EProtocol). Es zeigt die Modulo-16-Zählerweiterschaltung innerhalb der E2E-Zustandsbehandlung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Zustandsvariable: <code>State-&gt;Counter</code> (Zustandszähler, Wertebereich 0 bis 15).</li>\n<li>Kontrollknoten: Startknoten <code>Increment State-&gt;Counter</code>, Verzweigungsknoten mit der Guard-Prüfung <code>State-&gt;Counter &lt; 15 ?</code>, Zusammenführungsknoten, Endknoten.</li>\n<li>Aktionen: Inkrementierungsaktion <code>State-&gt;Counter ++</code>, Reset-Aktion <code>State-&gt; Counter = 0</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausführung beginnt am Startknoten <code>Increment State-&gt;Counter</code>.</li>\n<li>Am Verzweigungsknoten wird die Bedingung <code>State-&gt;Counter &lt; 15 ?</code> geprüft.</li>\n<li>Ergibt die Bedingung <code>[TRUE]</code>, wird die Aktion <code>State-&gt;Counter ++</code> ausgeführt.</li>\n<li>Ergibt die Bedingung <code>[FALSE]</code> (Zählerwert ist 15), wird die Aktion <code>State-&gt; Counter = 0</code> ausgeführt.</li>\n<li>Beide Zweige münden in den Zusammenführungsknoten und führen zum Aktivitätsendknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normative Zählerfortschaltung für E2E-Profile mit 4-Bit-Zähler ohne Gateway-/ForwardStatus-Sonderbehandlung. Bei Erreichen des Werts 15 springt der Zähler im nächsten Schritt auf 0 zurück. Die Implementierung muss sicherstellen, dass dieser Ablauf bei jeder regulären Botschaftsgenerierung durchlaufen wird.</p>"}, {"id": "FIG-90e173f5e6049ed6", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses bei der zustandsabhängigen Zähleranpassung und -inkrementierung (Increment State->Counter) im AUTOSAR E2E-Protokoll (PRS_E2EProtocol). Das Diagramm modelliert die Vorwärtsstatus-Behandlung bei Nachrichtenweiterleitung sowie das zyklische Inkrementieren eines 4-Bit-Modulo-16-Zählers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Daten- und Zustandsstrukturen: <code>State-&gt;Counter</code> (Zählerwert), <code>Config-&gt;MaxDeltaCounterInit</code> (Konfigurationsparameter für den maximal zulässigen Zählersprung beim Initialisieren/Synchronisieren), <code>ForwardStatus</code> (Statusflag zur Sequenzintegrität mit Werten wie <code>E2E_P_REPEATED</code> und <code>E2E_P_WRONGSEQUENCE</code>).</li>\n<li>Kontrollknoten: Startknoten <code>Increment State-&gt;Counter</code>, drei aufeinanderfolgende Entscheidungsknoten (Decision Nodes), ein Zusammenführungsknoten (Merge Node), Endknoten (Activity Final Node).</li>\n<li>Aktionen: Zählersprung <code>State-&gt; Counter += Config-&gt;MaxDeltaCounterInit + 1</code>, Zähler-Reset <code>State-&gt; Counter = 0</code>, Inkrementierung <code>State-&gt;Counter ++</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Startknoten <code>Increment State-&gt;Counter</code>.</li>\n<li>Erster Verzweigungsknoten prüft, ob eine Wiederholung vorliegt (<code>ForwardStatus == E2E_P_REPEATED</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Keine Anpassung des Zählers; der Pfad führt direkt zum Zusammenführungsknoten.</li>\n<li>Wenn <code>[FALSE]</code>: Übergang zum zweiten Entscheidungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweiter Verzweigungsknoten prüft <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Ausführung von <code>State-&gt; Counter += Config-&gt;MaxDeltaCounterInit + 1</code>, danach Übergang zum Zusammenführungsknoten.</li>\n<li>Wenn <code>[FALSE]</code>: Übergang zum dritten Entscheidungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Dritter Verzweigungsknoten prüft den Überlauf <code>State-&gt;Counter &gt;= 15 ?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[TRUE]</code>: Ausführung von <code>State-&gt; Counter = 0</code>.</li>\n<li>Wenn <code>[FALSE]</code>: Ausführung von <code>State-&gt;Counter ++</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Alle drei aktiven Zweige bzw. der Bypass-Zweig münden im gemeinsamen Zusammenführungsknoten und enden im Final Node.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert das Verhalten bei fehlerhaften Sequenzen (<code>E2E_P_WRONGSEQUENCE</code>) und wiederholten Botschaften (<code>E2E_P_REPEATED</code>) im Forwarding-/Gateway-Szenario des E2E-Protokolls. Für Implementierer ist relevant, dass ein Sequenzfehler einen gezielten Sprung über das Akzeptanzfenster (<code>MaxDeltaCounterInit + 1</code>) erzwingt, während bei Duplikaten keine Zählerfortschaltung stattfindet. Bei normalem Fluss wird der Zähler modulo 16 zyklisch geführt.</p>"}], "trans": [{"from": "FIG-81986ec0ac893207", "to": "FIG-3d30d171b43656c1", "fr": "R1.3.0", "tr": "R1.5.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textumbruch bei Startknoten-Beschriftung von „Increment\\nState->Counter“ zu „Increment State\\n>Counter“ geändert.</li>\n<li>Beschriftung an der Verzweigungsraute: Zeilenumbruch und Sichtbarkeit der Bedingung („15 ?“ in zweiter Zeile dargestellt statt abgeschnittenes „?“).</li>\n</ul>"}, {"from": "FIG-3d30d171b43656c1", "to": "FIG-81986ec0ac893207", "fr": "R1.5.1", "tr": "R17-10_R1.2.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textumbruch bei Startknoten-Beschriftung von „Increment State\\n>Counter“ zurück zu „Increment\\nState->Counter“ geändert.</li>\n<li>Beschriftung an der Verzweigungsraute: Zeile mit „15 ?“ wieder verändert/abgeschnitten zu „?“.</li>\n</ul>"}, {"from": "FIG-81986ec0ac893207", "to": "FIG-0c08a6fe19bfbfd0", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0c08a6fe19bfbfd0", "to": "FIG-3d30d171b43656c1", "fr": "R18-03_R1.4.0", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textumbruch bei Startknoten-Beschriftung von „Increment\\nState->Counter“ zu „Increment State\\n>Counter“ geändert.</li>\n<li>Beschriftung an der Verzweigungsraute: Zeilenumbruch und Sichtbarkeit der Bedingung („15 ?“ in zweiter Zeile dargestellt statt abgeschnittenes „?“).</li>\n</ul>"}]};
